## Why This Is Asked
This question evaluates the ability to implement offline-first data flow with AsyncStorage, build simple UI components with FlatList, and manage state for search filtering.

## Key Concepts
- FlatList and RefreshControl for list rendering and pull-to-refresh functionality
- AsyncStorage for caching data locally with timestamps for stale data detection
- Local filtering with search input for instant, responsive filtering
- Offline-first UX patterns and proper state management

## Code Example
```javascript
import React, {useEffect, useState} from 'react';
import {FlatList, TextInput, View, Text, RefreshControl} from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';

const RestaurantsList = () => {
  const [restaurants, setRestaurants] = useState([]);
  const [filtered, setFiltered] = useState([]);
  const [search, setSearch] = useState('');
  const [refreshing, setRefreshing] = useState(false);

  const fetchRestaurants = async (forceRefresh = false) => {
    const cacheKey = 'restaurants_v1';

    if (!forceRefresh) {
      const cached = await AsyncStorage.getItem(cacheKey);
      if (cached) {
        const {data} = JSON.parse(cached);
        setRestaurants(data);
        setFiltered(data);
      }
    }

    const response = await fetch('https://api.example.com/restaurants');
    const data = await response.json();

    await AsyncStorage.setItem(cacheKey, JSON.stringify({data, timestamp: Date.now()}));
    setRestaurants(data);
    setFiltered(search ? data.filter(r => r.name.toLowerCase().includes(search.toLowerCase())) : data);
    setRefreshing(false);
  };

  useEffect(() => { fetchRestaurants(); }, []);

  const handleSearch = (text) => {
    setSearch(text);
    setFiltered(restaurants.filter(r => r.name.toLowerCase().includes(text.toLowerCase())));
  };

  return (
    <View>
      <TextInput placeholder="Search restaurants..." value={search} onChangeText={handleSearch} />
      <FlatList
        data={filtered}
        keyExtractor={(item) => item.id}
        renderItem={({item}) => <Text>{item.name}</Text>}
        refreshControl={<RefreshControl refreshing={refreshing} onRefresh={() => { setRefreshing(true); fetchRestaurants(true); }} />}
      />
    </View>
  );
};

export default RestaurantsList;
```

## Why This Is Asked
Tests ability to design a responsive image loading strategy that balances UX and data usage, incorporating network state, device capabilities, and offline caching in React Native.

## Key Concepts
- Variant selection logic using NetInfo, PixelRatio, and battery saver state
- Local caching strategy (Realm/SQLite) with TTL and cache busting
- Image loading lifecycle and prefetching to minimize jank

## Code Example
```javascript
import { useEffect, useState, useCallback } from 'react'
import NetInfo from '@react-native-community/netinfo'
import { PixelRatio } from 'react-native'

function useAdaptiveImage(sizes, baseUri) {
  const [uri, setUri] = useState(sizes.medium)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  const resolveVariant = useCallback((info) => {
    const bandwidth = info.type === 'wifi' ? 1000 : info.details?.speed ?? 500
    const dpr = PixelRatio.get()
    const batterySaver = info.batterySaverEnabled
    let chosen = sizes.medium
    if (!batterySaver && bandwidth > 800 && dpr >= 2) chosen = sizes.large
    else if (bandwidth < 400) chosen = sizes.thumb
    return chosen
  }, [sizes])

  useEffect(() => {
    let mounted = true
    NetInfo.fetch().then(info => {
      if (!mounted) return
      const variant = resolveVariant(info)
      setUri(variant)
      // pretend fetch/cache logic here
      setLoading(false)
    }).catch(err => {
      if (mounted) { setError(err); setLoading(false) }
    })
    return () => { mounted = false }
  }, [resolveVariant])

  const refresh = useCallback(() => {
    setLoading(true)
    NetInfo.fetch().then(info => {
      const variant = resolveVariant(info)
      setUri(variant)
      setLoading(false)
    }).catch(err => setError(err))
  }, [resolveVariant])

  return { uri, loading, error, refresh }
}
```

